local home = os.getenv("HOME")

hl.env("XDG_STATE_HOME", home .. "/.local/state")

hl.env("XDG_DATA_HOME", home .. "/.local/share")

hl.env("XDG_CONFIG_HOME", home .. "/.config")

hl.env("XDG_CACHE_HOME", home .. "/.cache")

hl.env("XDG_DESKTOP_DIR", home .. "/workspace")

hl.env("XDG_DOWNLOAD_DIR", home .. "/downloads")

hl.env("XDG_TEMPLATES_DIR", home .. "/.local/share/templates")

hl.env("XDG_PUBLICSHARE_DIR", home .. "/")

hl.env("XDG_DOCUMENTS_DIR", home .. "/docs")

hl.env("XDG_MUSIC_DIR", home .. "/media/music")

